const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '支点' },
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '阻力臂' },
      { kind: 'text', payload: '动力臂 : 阻力臂 = 2 : 1' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var DW = 720, DH = 480;
    var k = Math.min(W / DW, H / DH);
    var offX = (W - DW * k) / 2;
    var offY = (H - DH * k) / 2;
    function px(x) { return offX + x * k; }
    function py(y) { return offY + y * k; }
    function P(x, y) { return [px(x), py(y)]; }
    function S(p) { return [px(p[0]), py(p[1])]; }
    function seg(x1, y1, x2, y2) { return visualSdk.polyline([P(x1, y1), P(x2, y2)]); }

    var th = 15 * Math.PI / 180;
    var ux = Math.cos(th), uy = Math.sin(th);
    var nx = uy, ny = -ux;

    var F = [400, 348];
    var U = 90;
    var B = [F[0] + U * ux, F[1] + U * uy];
    var A = [F[0] - 2 * U * ux, F[1] - 2 * U * uy];
    var off = 40;
    var A2 = [A[0] + off * nx, A[1] + off * ny];
    var F2 = [F[0] + off * nx, F[1] + off * ny];
    var B2 = [B[0] + off * nx, B[1] + off * ny];

    var a = S(A), f = S(F), b = S(B), a2 = S(A2), f2 = S(F2), b2 = S(B2);

    var ground = seg(36, 380, 684, 380);
    var hatch = [];
    for (var x = 56; x <= 664; x += 40) {
      hatch = hatch.concat(seg(x, 380, x - 14, 396));
    }

    var fulcrum = visualSdk.polyline([P(400, 348), P(381, 380), P(419, 380), P(400, 348)]);
    var bar = visualSdk.polyline([a, b]);

    var ticks = visualSdk.polyline([a, a2])
      .concat(visualSdk.polyline([f, f2]))
      .concat(visualSdk.polyline([b, b2]));

    var dimPower = visualSdk.arrow(a2[0], a2[1], f2[0], f2[1], {})
      .concat(visualSdk.arrow(f2[0], f2[1], a2[0], a2[1], {}));
    var dimRes = visualSdk.arrow(f2[0], f2[1], b2[0], b2[1], {})
      .concat(visualSdk.arrow(b2[0], b2[1], f2[0], f2[1], {}));

    var push = visualSdk.arrow(px(226), py(248), px(226), py(294), {});

    var rock = visualSdk.polyline([
      P(478, 380), P(484, 352), P(508, 330), P(540, 314),
      P(572, 322), P(592, 352), P(598, 380), P(478, 380)
    ]);

    var leader = seg(400, 384, 400, 406);

    var labels = [
      { type: 'label', x: px(329), y: py(264), text: '动力臂', fontSize: 17 * k, anchor: 'middle' },
      { type: 'label', x: px(460), y: py(299), text: '阻力臂', fontSize: 17 * k, anchor: 'middle' },
      { type: 'label', x: px(400), y: py(422), text: '支点', fontSize: 17 * k, anchor: 'middle' },
      { type: 'label', x: px(360), y: py(452), text: '动力臂 : 阻力臂 = 2 : 1', fontSize: 15 * k, anchor: 'middle' }
    ];

    return {
      schemaVersion: 1,
      sceneId: 'crowbar-lever',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'ground', commands: ground },
        { id: 'hatch', commands: hatch },
        { id: 'fulcrum', commands: fulcrum },
        { id: 'bar', commands: bar },
        { id: 'ticks', commands: ticks },
        { id: 'dimPower', commands: dimPower },
        { id: 'dimRes', commands: dimRes },
        { id: 'push', commands: push },
        { id: 'rock', commands: rock },
        { id: 'leader', commands: leader }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'ground', stroke: '#26354a', strokeWidth: 2.6 * k, fill: 'none' },
        { type: 'path', pathId: 'hatch', stroke: '#6b7885', strokeWidth: 1.4 * k, fill: 'none' },
        { type: 'path', pathId: 'fulcrum', stroke: '#26354a', strokeWidth: 2 * k, fill: '#7f8b99' },
        { type: 'path', pathId: 'bar', stroke: '#3d3d46', strokeWidth: 8 * k, fill: 'none' },
        { type: 'path', pathId: 'ticks', stroke: '#2b6cb0', strokeWidth: 1.4 * k, fill: 'none' },
        { type: 'path', pathId: 'dimPower', stroke: '#2b6cb0', strokeWidth: 1.6 * k, fill: '#2b6cb0' },
        { type: 'path', pathId: 'dimRes', stroke: '#2b6cb0', strokeWidth: 1.6 * k, fill: '#2b6cb0' },
        { type: 'path', pathId: 'push', stroke: '#c0392b', strokeWidth: 1.8 * k, fill: '#c0392b' },
        { type: 'path', pathId: 'rock', stroke: '#26354a', strokeWidth: 2.4 * k, fill: '#b6bdc6' },
        { type: 'path', pathId: 'leader', stroke: '#26354a', strokeWidth: 1.2 * k, fill: 'none' }
      ].concat(labels) }
    };
  }
};
